   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Visualization
    */
	public Visualization createVisualization( CreateVisualizationCommand command )
    throws ProcessingException, IllegalArgumentException {

		Visualization entity = new Visualization();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	VisualizationValidator.getInstance().validate( command );    

            entity.setVisualizationId( command.getVisualizationId() );
            entity.setTitle( command.getTitle() );
            entity.setOptions( command.getOptions() );
            entity.setChartType( command.getChartType() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of Visualization {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Visualization - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateVisualizationCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Visualization
    */
    public Visualization updateVisualization( UpdateVisualizationCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Visualization entity = new Visualization();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	VisualizationValidator.getInstance().validate( command );    

            entity.setVisualizationId( command.getVisualizationId() );
            entity.setTitle( command.getTitle() );
            entity.setOptions( command.getOptions() );
            entity.setDashboard( command.getDashboard() );
            entity.setReport( command.getReport() );
            entity.setMetrics( command.getMetrics() );
            entity.setDimensions( command.getDimensions() );
            entity.setDatasets( command.getDatasets() );
            entity.setChartType( command.getChartType() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.log( Level.INFO, "done saving of Visualization {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Visualization - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
