    /**
     * Method to retrieve the Visualization via VisualizationFetchOneSummary
     * @param 	summary VisualizationFetchOneSummary 
     * @return 	VisualizationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Visualization getVisualization( VisualizationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "VisualizationFetchOneSummary arg cannot be null" );
    	
    	Visualization entity = null;
    	UUID id = summary.getVisualizationId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	VisualizationValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a Visualization using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Visualization with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Visualizations
     *
     * @return 	List<Visualization> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Visualization> getAllVisualization() 
    throws ProcessingException {
        List<Visualization> list = null;

        try {        	
        	list = projector.findAll( new FindAllVisualizationQuery() );
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Visualization";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Dashboard on Visualization
     * @param		command AssignDashboardToVisualizationCommand	
     * @exception	ProcessingException
     */     
	public void assignDashboard( AssignDashboardToVisualizationCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	VisualizationValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignDashboard(command.getVisualizationId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Dashboard using id " + command.getVisualizationId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

